import{_ as o,C as s,o as d,c as l,a4 as r,b as n,w as a,a as i,E as h,a5 as p}from"./chunks/framework.9tZL7ZIQ.js";const C=JSON.parse('{"title":"伯克希尔 vs 标普500 · 六十年业绩对比","description":"巴菲特1965年接管伯克希尔以来的长期业绩与标普500指数对比可视化","frontmatter":{"title":"伯克希尔 vs 标普500 · 六十年业绩对比","description":"巴菲特1965年接管伯克希尔以来的长期业绩与标普500指数对比可视化"},"headers":[],"relativePath":"06_visualization/berkshire-vs-sp500.md","filePath":"06_visualization/berkshire-vs-sp500.md"}'),b={name:"06_visualization/berkshire-vs-sp500.md"};function g(c,t,u,_,m,k){const e=s("Mermaid");return d(),l("div",null,[t[1]||(t[1]=r('<h1 id="伯克希尔-vs-标普500-·-六十年业绩对比" tabindex="-1">伯克希尔 vs 标普500 · 六十年业绩对比 <a class="header-anchor" href="#伯克希尔-vs-标普500-·-六十年业绩对比" aria-label="Permalink to &quot;伯克希尔 vs 标普500 · 六十年业绩对比&quot;">​</a></h1><h2 id="导语" tabindex="-1">导语 <a class="header-anchor" href="#导语" aria-label="Permalink to &quot;导语&quot;">​</a></h2><p>1965年，巴菲特正式接管伯克希尔·哈撒韦。彼时，这家濒临破产的纺织厂股价约为<strong>19美元</strong>；截至2024年底，伯克希尔A类股收于<strong>约62万美元</strong>，涨幅超过<strong>3万倍</strong>。同期，标普500指数从1964年底的约<strong>95点</strong>涨至2024年底的约<strong>5,800点</strong>，涨幅约<strong>61倍</strong>。</p><p>六十年复利的威力，足以将19美元变成亿万美元——这不是神话，而是数学。</p><hr><h2 id="一、每十年年化收益率对比" tabindex="-1">一、每十年年化收益率对比 <a class="header-anchor" href="#一、每十年年化收益率对比" aria-label="Permalink to &quot;一、每十年年化收益率对比&quot;">​</a></h2><blockquote><p>巴菲特曾多次强调：「复利是神奇的力量，是世界第八大奇迹。理解它的人赚取它，不理解的人支付它。」</p></blockquote><p>以下图表展示各十年区间，伯克希尔与标普500的年化收益率对比：</p>',8)),(d(),n(p,null,{default:a(()=>[h(e,{id:"mermaid-24",class:"mermaid",graph:"xychart-beta%0A%20%20%20%20title%20%22%E6%AF%8F%E5%8D%81%E5%B9%B4%E5%B9%B4%E5%8C%96%E6%94%B6%E7%9B%8A%E7%8E%87%E5%AF%B9%E6%AF%94%20(%25)%22%0A%20%20%20%20x-axis%20%5B1965%2C1975%2C1985%2C1995%2C2005%2C2015%2C2024%5D%0A%20%20%20%20y-axis%20%22%E5%B9%B4%E5%8C%96%E6%94%B6%E7%9B%8A%E7%8E%87%20%25%22%20-10%20--%3E%2040%0A%20%20%20%20bar%20%5B15.7%2C%2032.5%2C%2028.2%2C%2024.1%2C%209.3%2C%2012.5%2C%2019.8%5D%0A%20%20%20%20line%20%5B5.3%2C%206.2%2C%2017.5%2C%2018.3%2C%207.3%2C%2014.5%2C%2013.1%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<p>::: legend 图例</p><ul><li><strong>深色柱</strong>（bar）：伯克希尔·哈撒韦年化收益率</li><li><strong>折线</strong>（line）：标普500指数年化收益率 :::</li></ul><h3 id="图表解读" tabindex="-1">图表解读 <a class="header-anchor" href="#图表解读" aria-label="Permalink to &quot;图表解读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>十年区间</th><th>伯克希尔年化</th><th>标普500年化</th><th>伯克希尔超额收益</th></tr></thead><tbody><tr><td>1965–1975</td><td>15.7%</td><td>5.3%</td><td>+10.4%</td></tr><tr><td>1975–1985</td><td>32.5%</td><td>6.2%</td><td>+26.3%</td></tr><tr><td>1985–1995</td><td>28.2%</td><td>17.5%</td><td>+10.7%</td></tr><tr><td>1995–2005</td><td>24.1%</td><td>18.3%</td><td>+5.8%</td></tr><tr><td>2005–2015</td><td>9.3%</td><td>7.3%</td><td>+2.0%</td></tr><tr><td>2015–2024</td><td>12.5%</td><td>13.1%</td><td>-0.6%</td></tr></tbody></table><blockquote><p>⚠️ <strong>说明</strong>：2020年代以来，伯克希尔的相对表现有所收敛，这与巴菲特已超过94岁、规模过大难以持续超额增长有关。但59年的整体记录依然无可比拟。</p></blockquote><hr><h2 id="二、累计收益对比-「-1投资」的滚雪球" tabindex="-1">二、累计收益对比：「$1投资」的滚雪球 <a class="header-anchor" href="#二、累计收益对比-「-1投资」的滚雪球" aria-label="Permalink to &quot;二、累计收益对比：「$1投资」的滚雪球&quot;">​</a></h2><blockquote><p>巴菲特在1991年致股东信中写道：「人生就像滚雪球，重要的是找到很湿的雪和很长的山坡。」</p></blockquote><p>1965年在伯克希尔投入<strong>1美元</strong>，2024年价值超过<strong>400万美元</strong>。以下表格展示了关键年份的累计增长对比：</p><table tabindex="0"><thead><tr><th>年份</th><th>伯克希尔（$1 →）</th><th>标普500（$1 →）</th><th>超额倍数</th><th>说明</th></tr></thead><tbody><tr><td>1965</td><td>$1</td><td>$1</td><td>—</td><td>巴菲特接管伯克希尔</td></tr><tr><td>1975</td><td>$5.3</td><td>$1.7</td><td><strong>3.1x</strong></td><td>十年3倍差距</td></tr><tr><td>1985</td><td>$88.5</td><td>$6.5</td><td><strong>13.6x</strong></td><td>蓝筹印花+喜诗糖果发力</td></tr><tr><td>1995</td><td>$3,218</td><td>$22.1</td><td><strong>145.6x</strong></td><td>《财富》封面报道「奥马哈先知」</td></tr><tr><td>2005</td><td>$27,895</td><td>$71.6</td><td><strong>389.6x</strong></td><td>所罗门丑闻后重建</td></tr><tr><td>2015</td><td>$626,607</td><td>$206.2</td><td><strong>3,039.8x</strong></td><td>金融危机后稳健复苏</td></tr><tr><td>2024</td><td>$4,384,748</td><td>$330.2</td><td><strong>13,280x</strong></td><td>2024年末最新数据</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">数据说明</p><ul><li>伯克希尔数据基于账面净资产（Book Value）增速，是巴菲特在股东信中一贯使用的衡量标准</li><li>标普500数据为含股息再投资的总回报</li><li>2024年数据为估算值，精确数字以伯克希尔年报为准</li></ul></div><hr><h2 id="三、复利的威力-为什么差距如此之大" tabindex="-1">三、复利的威力：为什么差距如此之大？ <a class="header-anchor" href="#三、复利的威力-为什么差距如此之大" aria-label="Permalink to &quot;三、复利的威力：为什么差距如此之大？&quot;">​</a></h2><p>两个数字的对比值得深思：</p><ul><li><strong>标普500</strong>：60年61倍 → 年化约<strong>9.7%</strong></li><li><strong>伯克希尔</strong>：60年438万倍 → 年化约<strong>19.4%</strong></li></ul><p>看起来差距不大——年化只多了约10个百分点。但正是这个10个百分点，在60年的复利作用下，将61倍放大到了<strong>438万倍</strong>。</p><p>巴菲特在2014年致股东信中做过一个著名的计算：</p><blockquote><p><em>「1950年我初涉股市时，如果你当时投入1.5万美元买进一只低佣金的道琼斯指数基金，现在这笔钱大约值50万美元——年化收益约8.5%。」</em></p><p><em>「但如果你当时把这1.5万美元交给我打理，60年后会变成约50亿美元——年化收益约21%。」</em></p></blockquote><p><strong>复利的本质</strong>：不是比谁赚得快，而是比谁活得长、滚得久。</p><hr><h2 id="四、历史上的低谷与挑战" tabindex="-1">四、历史上的低谷与挑战 <a class="header-anchor" href="#四、历史上的低谷与挑战" aria-label="Permalink to &quot;四、历史上的低谷与挑战&quot;">​</a></h2><p>超额收益并非线性的。伯克希尔在以下时期曾大幅跑输大盘：</p><table tabindex="0"><thead><tr><th>时期</th><th>背景</th><th>跑输幅度</th></tr></thead><tbody><tr><td>1999–2000</td><td>互联网泡沫顶峰</td><td>约30%+</td></tr><tr><td>2008–2009</td><td>全球金融危机</td><td>与指数接近</td></tr><tr><td>2016–2020</td><td>科技股狂飙</td><td>约10–15%</td></tr><tr><td>2021</td><td>疫情期间反弹</td><td>约20%</td></tr></tbody></table><blockquote><p><strong>关键教训</strong>：即使是最伟大的投资者，也会经历长期跑输大盘的阶段。但真正重要的不是某一年、某三年，而是<strong>二十年、三十年、五十年</strong>的维度。</p></blockquote><hr><h2 id="五、深入阅读" tabindex="-1">五、深入阅读 <a class="header-anchor" href="#五、深入阅读" aria-label="Permalink to &quot;五、深入阅读&quot;">​</a></h2><ul><li><a href="./../01_letters/1965年/翻译">巴菲特1965年致股东信</a> —— 接管伯克希尔的第一年</li><li><a href="./../01_letters/1983年/翻译">巴菲特1983年致股东信</a> —— 「经济商誉」与内在价值</li><li><a href="./../01_letters/1991年/翻译">巴菲特1991年致股东信</a> —— 「滚雪球」比喻首次系统阐述</li><li><a href="./../01_letters/1996年/翻译">巴菲特1996年致股东信</a> —— 关于长期投资与市场先生</li><li><a href="./../03_companies/伯克希尔哈撒韦">伯克希尔·哈撒韦公司</a> —— 公司完整介绍</li><li><a href="./../04_people/查理·芒格">查理·芒格</a> —— 复利思维的最佳搭档</li></ul><hr><blockquote><p><em>「时间是伟大企业的朋友，是平庸企业的敌人。」—— 沃伦·巴菲特</em></p></blockquote>',29))])}const x=o(b,[["render",g]]);export{C as __pageData,x as default};
